arguments.cmd:
node -e '
const fs = require("fs");
const eslintrc = JSON.parse(fs.readFileSync(".eslintrc", "utf8"));
eslintrc.overrides.forEach(override => {
  if (override.extends && override.extends.includes("plugin:jest/all")) {
    if (!override.rules) {
      override.rules = {};
    }
    override.rules["jest/require-hook"] = "off";
  }
});
fs.writeFileSync(".eslintrc", JSON.stringify(eslintrc, null, 2) + "\n", "utf8");
'

